package calc;

/// Signals that an expression cannot be evaluated: a syntax error, division by zero, or overflow.
final class EvaluationException extends Exception {
    EvaluationException(String message) {
        super(message, null, false, false);
    }
}

package calc;

/// Recursive-descent evaluator for signed 64-bit integer expressions.
///
/// Grammar (spaces and tabs may appear between tokens):
/// ```
/// expr    := term    (('+' | '-') term)*
/// term    := unary   (('*' | '/' | '%') unary)*
/// unary   := '-' unary | primary
/// primary := NUMBER | '(' expr ')'
/// ```
/// The input is a range of bytes, so any non-ASCII byte is simply a syntax error.
final class Evaluator {
    private final byte[] buf;
    private final int end;
    private int pos;

    private Evaluator(byte[] buf, int start, int end) {
        this.buf = buf;
        this.pos = start;
        this.end = end;
    }

    /// Evaluates the expression held in `buf[start, end)`.
    static long evaluate(byte[] buf, int start, int end) throws EvaluationException {
        Evaluator evaluator = new Evaluator(buf, start, end);
        long value = evaluator.expr();
        if (evaluator.peek() != -1) {
            throw new EvaluationException("unexpected character at offset " + (evaluator.pos - start));
        }
        return value;
    }

    private long expr() throws EvaluationException {
        long value = term();
        while (true) {
            int c = peek();
            if (c != '+' && c != '-') {
                return value;
            }
            pos++;
            value = apply((char) c, value, term());
        }
    }

    private long term() throws EvaluationException {
        long value = unary();
        while (true) {
            int c = peek();
            if (c == '*' || c == '/' || c == '%') {
                pos++;
                value = apply((char) c, value, unary());
            } else {
                return value;
            }
        }
    }

    private long unary() throws EvaluationException {
        if (peek() == '-') {
            pos++;
            long operand = unary();
            if (operand == Long.MIN_VALUE) {
                throw new EvaluationException("overflow");
            }
            return -operand;
        }
        return primary();
    }

    private long primary() throws EvaluationException {
        int c = peek();
        if (c == '(') {
            pos++;
            long value = expr();
            if (peek() != ')') {
                throw new EvaluationException("expected ')'");
            }
            pos++;
            return value;
        }
        if (c >= '0' && c <= '9') {
            return number();
        }
        throw new EvaluationException("expected operand");
    }

    private long number() throws EvaluationException {
        long value = 0;
        while (pos < end && buf[pos] >= '0' && buf[pos] <= '9') {
            int digit = buf[pos++] - '0';
            if (value > (Long.MAX_VALUE - digit) / 10) {
                throw new EvaluationException("literal out of range");
            }
            value = value * 10 + digit;
        }
        return value;
    }

    private static long apply(char op, long left, long right) throws EvaluationException {
        try {
            return switch (op) {
                case '+' -> Math.addExact(left, right);
                case '-' -> Math.subtractExact(left, right);
                case '*' -> Math.multiplyExact(left, right);
                case '/' -> {
                    if (right == 0) {
                        throw new EvaluationException("division by zero");
                    }
                    yield Math.divideExact(left, right);
                }
                case '%' -> {
                    if (right == 0) {
                        throw new EvaluationException("division by zero");
                    }
                    yield left % right; // Long.MIN_VALUE % -1 is 0, not an overflow
                }
                default -> throw new IllegalArgumentException("unknown operator: " + op);
            };
        } catch (ArithmeticException e) {
            throw new EvaluationException("overflow");
        }
    }

    /// Skips blanks and returns the next byte without consuming it, or -1 at end of input.
    private int peek() {
        while (pos < end && (buf[pos] == ' ' || buf[pos] == '\t')) {
            pos++;
        }
        return pos < end ? buf[pos] & 0xFF : -1;
    }
}

package calc;

import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.FileDescriptor;
import java.io.FileOutputStream;
import java.nio.charset.StandardCharsets;

/// Reads one expression per line from standard input and prints its value or `error`.
public final class Main {
    /// Deeply nested input recurses deeply; run on a thread with a generous stack.
    private static final long STACK_BYTES = 1L << 30;

    private Main() {}

    public static void main(String[] args) throws Exception {
        Throwable[] failure = new Throwable[1];
        Thread worker = new Thread(null, () -> {
            try {
                run();
            } catch (IOException e) {
                failure[0] = e;
            }
        }, "calc", STACK_BYTES);
        worker.start();
        worker.join();
        if (failure[0] != null) {
            System.err.println("calc: " + failure[0].getMessage());
            System.exit(1);
        }
    }

    private static void run() throws IOException {
        byte[] input = System.in.readAllBytes();
        OutputStream out = new BufferedOutputStream(new FileOutputStream(FileDescriptor.out), 1 << 16);
        int lineStart = 0;
        while (lineStart < input.length) {
            int lineEnd = lineStart;
            while (lineEnd < input.length && input[lineEnd] != '\n') {
                lineEnd++;
            }
            if (!isBlank(input, lineStart, lineEnd)) {
                out.write(evaluateLine(input, lineStart, lineEnd).getBytes(StandardCharsets.US_ASCII));
                out.write('\n');
            }
            lineStart = lineEnd + 1;
        }
        out.flush();
    }

    private static String evaluateLine(byte[] input, int start, int end) {
        try {
            return Long.toString(Evaluator.evaluate(input, start, end));
        } catch (EvaluationException | StackOverflowError e) {
            return "error";
        }
    }

    private static boolean isBlank(byte[] buf, int start, int end) {
        for (int i = start; i < end; i++) {
            if (buf[i] != ' ' && buf[i] != '\t') {
                return false;
            }
        }
        return true;
    }
}
